CREATE FUNCTION public.recycling_action(action text,payload jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE uid uuid:=auth.uid(); adm boolean:=public.has_role(auth.uid(),'admin'); rid uuid; r public.recycling_requests; partner public.recycling_partners; cfg public.recycling_settings; weights jsonb; kg numeric; target uuid; balance numeric; reward jsonb; vid uuid; period date; winners jsonb; winner jsonb; chosen integer; o public.orders; v public.green_vouchers; discount numeric; key text;
BEGIN
IF uid IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF;
SELECT * INTO cfg FROM public.recycling_settings WHERE id; IF NOT FOUND THEN cfg.points_per_kg:=10; cfg.rewards:='[{"points":100,"percent":5},{"points":250,"percent":10},{"points":500,"percent":15}]'; cfg.winner_percents:=ARRAY[20,15,10]; cfg.expiry_days:=30; cfg.max_discount:=100; cfg.minimum_order:=0; END IF;
IF action IN ('approve_business','partner','configure','finalize','issue') AND NOT adm THEN RAISE EXCEPTION 'Administrator only'; END IF;
IF action='approve_business' THEN target:=(payload->>'userId')::uuid; IF target=uid OR NOT public.has_role(target,'buyer') THEN RAISE EXCEPTION 'Independent approval required'; END IF; INSERT INTO public.recycling_businesses(user_id,approved) VALUES(target,(payload->>'approved')::boolean) ON CONFLICT(user_id) DO UPDATE SET approved=EXCLUDED.approved; RETURN '{}';
ELSIF action='partner' THEN target:=(payload->>'userId')::uuid; IF target=uid THEN RAISE EXCEPTION 'Independent approval required'; END IF; INSERT INTO public.recycling_partners(user_id,company_name,approved) VALUES(target,payload->>'name',(payload->>'approved')::boolean) ON CONFLICT(user_id) DO UPDATE SET company_name=EXCLUDED.company_name,approved=EXCLUDED.approved; RETURN '{}';
ELSIF action='opt_out' THEN UPDATE public.recycling_businesses SET public_ranking=(payload->>'participate')::boolean WHERE user_id=uid; IF NOT FOUND THEN RAISE EXCEPTION 'Approved business required'; END IF; RETURN '{}';
ELSIF action='configure' THEN
IF jsonb_typeof(payload->'rewards') IS DISTINCT FROM 'array' OR jsonb_array_length(payload->'rewards') NOT BETWEEN 1 AND 20 THEN RAISE EXCEPTION 'Invalid rewards'; END IF;
FOR reward IN SELECT * FROM jsonb_array_elements(payload->'rewards') LOOP IF (reward->>'points') IS NULL OR (reward->>'percent') IS NULL OR (reward->>'points')::numeric<=0 OR (reward->>'points')::numeric<>trunc((reward->>'points')::numeric) OR (reward->>'percent')::integer NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Invalid reward'; END IF; END LOOP;
IF jsonb_array_length(payload->'winners')<>3 THEN RAISE EXCEPTION 'Three rewards required'; END IF; FOR reward IN SELECT * FROM jsonb_array_elements(payload->'winners') LOOP IF reward::text::int NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Invalid winner reward'; END IF; END LOOP;
INSERT INTO public.recycling_settings(id,points_per_kg,rewards,winner_percents,expiry_days,max_discount,minimum_order) VALUES(true,(payload->>'rate')::numeric,payload->'rewards',ARRAY(SELECT value::text::int FROM jsonb_array_elements(payload->'winners')),(payload->>'days')::int,(payload->>'cap')::numeric,(payload->>'minimum')::numeric) ON CONFLICT(id) DO UPDATE SET points_per_kg=EXCLUDED.points_per_kg,rewards=EXCLUDED.rewards,winner_percents=EXCLUDED.winner_percents,expiry_days=EXCLUDED.expiry_days,max_discount=EXCLUDED.max_discount,minimum_order=EXCLUDED.minimum_order; RETURN '{}';
ELSIF action='consent' THEN target:=(payload->>'supplierId')::uuid; IF NOT EXISTS(SELECT 1 FROM public.supplier_profiles WHERE id=target AND user_id=uid AND verification_status='approved') THEN RAISE EXCEPTION 'Approved supplier owner required'; END IF; INSERT INTO public.green_supplier_consent(supplier_id,approved) VALUES(target,(payload->>'approved')::boolean) ON CONFLICT(supplier_id) DO UPDATE SET approved=EXCLUDED.approved,updated_at=now(); RETURN '{}';
ELSIF action='submit' THEN
IF NOT public.group_buyer_eligible() OR NOT EXISTS(SELECT 1 FROM public.recycling_businesses WHERE user_id=uid AND approved) THEN RAISE EXCEPTION 'Approved business required'; END IF;
weights:=payload->'weights'; kg:=public.recycling_weights(weights);
INSERT INTO public.recycling_requests(buyer_id,estimated_weights,city,location,request_key) VALUES(uid,weights,payload->>'city',payload->>'location',(payload->>'key')::uuid) ON CONFLICT(request_key) DO NOTHING RETURNING id INTO rid;
IF rid IS NULL THEN SELECT id INTO rid FROM public.recycling_requests WHERE request_key=(payload->>'key')::uuid AND buyer_id=uid; IF rid IS NULL THEN RAISE EXCEPTION 'Invalid retry'; END IF; END IF; RETURN jsonb_build_object('id',rid);
ELSIF action IN ('redeem','issue') THEN
target:=CASE WHEN action='issue' THEN (payload->>'userId')::uuid ELSE uid END; IF NOT EXISTS(SELECT 1 FROM public.recycling_businesses WHERE user_id=target AND approved) THEN RAISE EXCEPTION 'Approved business required'; END IF;
IF action='issue' AND target=uid THEN RAISE EXCEPTION 'Independent issuer required'; END IF;
PERFORM 1 FROM public.recycling_businesses WHERE user_id=target FOR UPDATE;
key:=CASE WHEN action='issue' THEN 'manual:' ELSE 'redeem:' END||((payload->>'key')::uuid)::text; SELECT id INTO vid FROM public.green_vouchers WHERE source_key=key AND user_id=target; IF FOUND THEN RETURN jsonb_build_object('id',vid); END IF;
IF action='redeem' THEN SELECT value INTO reward FROM jsonb_array_elements(cfg.rewards) WHERE (value->>'points')::numeric=(payload->>'points')::numeric LIMIT 1; IF reward IS NULL THEN RAISE EXCEPTION 'Invalid reward'; END IF;
SELECT coalesce(sum(amount),0) INTO balance FROM public.green_points_ledger WHERE user_id=uid; IF balance<(reward->>'points')::numeric THEN RAISE EXCEPTION 'Insufficient points'; END IF; chosen:=(reward->>'percent')::int;
INSERT INTO public.green_points_ledger(user_id,amount,source_key) VALUES(uid,-(reward->>'points')::numeric,key);
ELSE chosen:=(payload->>'percent')::int; END IF;
INSERT INTO public.green_vouchers(user_id,percent,maximum_discount,minimum_order,expires_at,source_key) VALUES(target,chosen,cfg.max_discount,cfg.minimum_order,now()+make_interval(days=>cfg.expiry_days),key) RETURNING id INTO vid; RETURN jsonb_build_object('id',vid);
ELSIF action='finalize' THEN
period:=(payload->>'period')::date; IF period IS NULL OR period<>date_trunc('month',period)::date OR period>=date_trunc('month',now() AT TIME ZONE 'Asia/Gaza')::date THEN RAISE EXCEPTION 'Only closed months'; END IF;
PERFORM pg_advisory_xact_lock(hashtext('green-month:'||period::text)); IF EXISTS(SELECT 1 FROM public.recycling_months m WHERE m.period=period) THEN RETURN '{}'; END IF;
winners:=public.recycling_rankings(period); IF EXISTS(SELECT 1 FROM jsonb_array_elements(winners) x WHERE (x->>'user_id')::uuid=uid AND (x->>'rank')::int<=3) THEN RAISE EXCEPTION 'Independent finalizer required'; END IF;
INSERT INTO public.recycling_months(period,finalized_by,results) VALUES(period,uid,winners);
FOR winner IN SELECT * FROM jsonb_array_elements(winners) LOOP IF (winner->>'rank')::int<=3 THEN INSERT INTO public.green_vouchers(user_id,percent,maximum_discount,minimum_order,expires_at,source_key) VALUES((winner->>'user_id')::uuid,cfg.winner_percents[(winner->>'rank')::int],cfg.max_discount,cfg.minimum_order,now()+make_interval(days=>cfg.expiry_days),'monthly:'||period||':'||(winner->>'user_id')) ON CONFLICT(source_key) DO NOTHING; END IF; END LOOP; RETURN '{}';
ELSIF action='apply' THEN
SELECT * INTO o FROM public.orders WHERE id=(payload->>'orderId')::uuid FOR UPDATE; IF NOT FOUND OR o.buyer_id<>uid OR o.status<>'pending' OR o.campaign_id IS NOT NULL OR o.is_demo THEN RAISE EXCEPTION 'Ineligible order'; END IF;
SELECT * INTO v FROM public.green_vouchers WHERE id=(payload->>'voucherId')::uuid FOR UPDATE; IF NOT FOUND OR v.user_id<>uid THEN RAISE EXCEPTION 'Invalid voucher'; END IF;
IF v.used_order_id=o.id THEN RETURN '{}'; END IF;
IF v.used_at IS NOT NULL OR v.expires_at<=now() OR o.green_voucher_id IS NOT NULL OR o.total<v.minimum_order OR NOT EXISTS(SELECT 1 FROM public.recycling_businesses WHERE user_id=uid AND approved) OR NOT EXISTS(SELECT 1 FROM public.green_supplier_consent WHERE supplier_id=o.supplier_id AND approved) THEN RAISE EXCEPTION 'Voucher not applicable'; END IF;
discount:=least(round(o.total*v.percent/100,2),v.maximum_discount,o.total); UPDATE public.orders SET total=total-discount,green_voucher_id=v.id,green_discount=discount WHERE id=o.id; UPDATE public.green_vouchers SET used_order_id=o.id,used_at=now(),is_demo=false WHERE id=v.id; RETURN jsonb_build_object('discount',discount);
END IF;
rid:=(payload->>'id')::uuid; SELECT * INTO r FROM public.recycling_requests WHERE id=rid FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Request not found'; END IF;
SELECT * INTO partner FROM public.recycling_partners WHERE id=r.partner_id;
IF action='assign' THEN IF NOT adm OR uid=r.buyer_id OR r.status NOT IN ('submitted','assigned') THEN RAISE EXCEPTION 'Assignment not allowed'; END IF; SELECT * INTO partner FROM public.recycling_partners WHERE id=(payload->>'partnerId')::uuid AND approved; IF NOT FOUND OR partner.user_id=r.buyer_id THEN RAISE EXCEPTION 'Independent approved partner required'; END IF; UPDATE public.recycling_requests SET partner_id=partner.id,status='assigned' WHERE id=rid;
ELSIF action='reject' THEN IF NOT adm OR uid=r.buyer_id OR uid=partner.user_id OR r.status NOT IN ('submitted','collected') THEN RAISE EXCEPTION 'Reject not allowed'; END IF; UPDATE public.recycling_requests SET status='rejected' WHERE id=rid;
ELSIF action='accept' THEN IF partner.user_id IS DISTINCT FROM uid OR NOT partner.approved OR r.status<>'assigned' THEN RAISE EXCEPTION 'Assigned partner required'; END IF; UPDATE public.recycling_requests SET status='accepted' WHERE id=rid;
ELSIF action='schedule' THEN IF partner.user_id IS DISTINCT FROM uid OR NOT partner.approved OR r.status NOT IN ('accepted','scheduled') OR (payload->>'date') IS NULL OR (payload->>'date')::timestamptz<=now() THEN RAISE EXCEPTION 'Invalid schedule'; END IF; UPDATE public.recycling_requests SET status='scheduled',scheduled_at=(payload->>'date')::timestamptz WHERE id=rid;
ELSIF action='collect' THEN IF partner.user_id IS DISTINCT FROM uid OR NOT partner.approved OR r.status NOT IN ('scheduled','collected') THEN RAISE EXCEPTION 'Assigned scheduled pickup required'; END IF; kg:=public.recycling_weights(payload->'weights'); IF EXISTS(SELECT 1 FROM jsonb_object_keys(payload->'weights') k WHERE NOT r.estimated_weights ? k) THEN RAISE EXCEPTION 'Material not requested'; END IF; IF NOT EXISTS(SELECT 1 FROM public.recycling_files WHERE request_id=rid AND kind='receipt' AND uploaded_by=uid) THEN RAISE EXCEPTION 'Receipt required'; END IF; UPDATE public.recycling_requests SET actual_weights=payload->'weights',status='collected',collected_at=coalesce(collected_at,now()) WHERE id=rid;
ELSIF action='verify' THEN IF NOT adm OR uid=r.buyer_id OR uid=partner.user_id THEN RAISE EXCEPTION 'Independent administrator required'; END IF; IF r.status='verified' THEN RETURN '{}'; END IF; IF r.status<>'collected' THEN RAISE EXCEPTION 'Collected evidence required'; END IF; kg:=public.recycling_weights(payload->'weights'); IF EXISTS(SELECT 1 FROM jsonb_each(payload->'weights') w WHERE NOT r.actual_weights ? w.key OR w.value::text::numeric>(r.actual_weights->>w.key)::numeric) THEN RAISE EXCEPTION 'Weight exceeds collected amount'; END IF; IF coalesce((payload->>'recycled')::boolean,false) AND NOT EXISTS(SELECT 1 FROM public.recycling_files WHERE request_id=rid AND kind='evidence') THEN RAISE EXCEPTION 'Recycling evidence required'; END IF;
PERFORM 1 FROM public.recycling_businesses WHERE user_id=r.buyer_id FOR UPDATE;
UPDATE public.recycling_requests SET verified_kg=kg,verified_at=now(),verified_by=uid,status='verified',confirmed_recycled=coalesce((payload->>'recycled')::boolean,false),actual_weights=payload->'weights' WHERE id=rid;
IF round(kg*cfg.points_per_kg,3)>0 THEN INSERT INTO public.green_points_ledger(user_id,amount,source_key,request_id) VALUES(r.buyer_id,round(kg*cfg.points_per_kg,3),'collection:'||rid,rid) ON CONFLICT(source_key) DO NOTHING; END IF;
ELSIF action='file' THEN IF NOT public.recycling_access(rid) OR length(payload->>'path')>500 OR payload->>'path' NOT LIKE rid::text||'/%' OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='recycling-evidence' AND name=payload->>'path' AND owner_id=uid::text) THEN RAISE EXCEPTION 'Invalid uploaded file'; END IF;
IF NOT ((uid=r.buyer_id AND r.status='submitted' AND payload->>'kind'='photo') OR (partner.user_id=uid AND partner.approved AND r.status IN ('accepted','scheduled','collected') AND payload->>'kind' IN ('receipt','evidence'))) THEN RAISE EXCEPTION 'File not permitted'; END IF;
INSERT INTO public.recycling_files(request_id,kind,storage_path,file_name,uploaded_by) VALUES(rid,payload->>'kind',payload->>'path',payload->>'name',uid);
ELSE RAISE EXCEPTION 'Unknown action'; END IF; RETURN '{}'; END $$;
REVOKE ALL ON FUNCTION public.recycling_action(text,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.recycling_action(text,jsonb) TO authenticated;
CREATE POLICY recycling_storage_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='recycling-evidence' AND EXISTS(SELECT 1 FROM public.recycling_requests WHERE id::text=(storage.foldername(name))[1] AND public.recycling_access(id)));
CREATE POLICY recycling_storage_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='recycling-evidence' AND EXISTS(SELECT 1 FROM public.recycling_requests r WHERE r.id::text=(storage.foldername(name))[1] AND ((r.buyer_id=auth.uid() AND r.status='submitted') OR (r.status IN ('accepted','scheduled','collected') AND EXISTS(SELECT 1 FROM public.recycling_partners p WHERE p.id=r.partner_id AND p.user_id=auth.uid() AND p.approved)))));
CREATE POLICY recycling_storage_cleanup ON storage.objects FOR DELETE TO authenticated USING(bucket_id='recycling-evidence' AND owner_id=auth.uid()::text AND NOT EXISTS(SELECT 1 FROM public.recycling_files WHERE storage_path=name));